def rolling_max(numbers: List[int]) -> List[int]:
    if not numbers:
        return []

    rolling_maxs = [numbers[0]]
    current_max = numbers[0]

    for num in numbers[1:]:
        if num > current_max:
            current_max = num
        rolling_maxs.append(current_max)

    return rolling_maxs

