def minPath(grid, k):
    N = len(grid)
    if N < 2 or k < 1:
        return []

    directions = [(0, 1), (1, 0), (-1, 0), (0, -1)]
    visited = set()
    min_path = []

    def dfs(x, y, path, steps):
        if steps == k:
            min_path = path[:]
            return
        if (x, y) in visited or steps > k:
            return
        visited.add((x, y))
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < N and 0 <= ny < N:
                dfs(nx, ny, path + [grid[nx][ny]], steps + 1)
        visited.remove((x, y))

    for i in range(N):
        for j in range(N):
            dfs(i, j, [grid[i][j]], 1)

    return min_path

