def solve(s):
    if not any(c.isalpha() for c in s):
        return s[::-1]

    result = []
    for c in s:
        if c.isalpha():
            if c.islower():
                result.append(c.upper())
            else:
                result.append(c.lower())
        else:
            result.append(c)

    return ''.join(result)

