def magic_square_test(matrix):
    n = len(matrix)
    if n == 0:
        return False

    # Check if the matrix is square
    for row in matrix:
        if len(row) != n:
            return False

    # Calculate the sum of the first row
    sum_first_row = sum(matrix[0])

    # Check if all rows have the same sum
    for row in matrix:
        if sum(row) != sum_first_row:
            return False

    # Check if all columns have the same sum
    for col in range(n):
        col_sum = sum(matrix[row][col] for row in range(n))
        if col_sum != sum_first_row:
            return False

    # Check if the main diagonal has the same sum
    main_diag_sum = sum(matrix[i][i] for i in range(n))
    if main_diag_sum != sum_first_row:
        return False

    # Check if the secondary diagonal has the same sum
    secondary_diag_sum = sum(matrix[i][n-i-1] for i in range(n))
    if secondary_diag_sum != sum_first_row:
        return False

    return True

def reverse_vowels(s):
    vowels = 'aeiouAEIOU'
    s_list = list(s)
    left, right = 0, len(s_list) - 1

    while left < right:
        if s_list[left] not in vowels:
            left += 1
        elif s_list[right] not in vowels:
            right -= 1
        else:
            s_list[left], s_list[right] = s_list[right], s_list[left]
            left += 1
            right -= 1

    return ''.join(s_list)

