def count_binary_seq(n):
    if n % 2 != 0:
        return 0

    total_sequences = 2 ** (2 * n)
    valid_sequences = 0

    for i in range(n):
        if (2 ** i) % 2 == 0:
            valid_sequences += total_sequences // 2

    return valid_sequences

