def maxAverageOfPath(matrix):
    n = len(matrix)
    if n == 0:
        return 0

    # Initialize the dp table
    dp = [[0] * n for _ in range(n)]

    # Fill the dp table
    for i in range(n):
        for j in range(n):
            if i == 0 and j == 0:
                dp[i][j] = matrix[i][j]
            elif i == 0:
                dp[i][j] = dp[i][j-1] + matrix[i][j]
            elif j == 0:
                dp[i][j] = dp[i-1][j] + matrix[i][j]
            else:
                dp[i][j] = max(dp[i-1][j], dp[i][j-1]) + matrix[i][j]

    # Calculate the maximum average
    max_avg = 0
    for i in range(n):
        for j in range(n):
            max_avg = max(max_avg, dp[i][j] / (i + j + 1))

    return max_avg

