        elif x == 6:
            return 'Six'
        elif x == 7:
            return 'Seven'
        elif x == 8:
            return 'Eight'
        else:
            return 'Nine'
    sorted_list, ans = (sorted(arr)[::-1], [])
    for x in sorted_list:
        if isinstance(x, int) and 0 <= x <= 9:
            ans.append(to_word(x))
    return ans

